        tecto_instructions = json.dumps(tecto, ensure_ascii=False)[:500] if tecto else ""

        if role == "grok":
            return f"""Ты — Грок, исследовательско-философский разум Мандалы.

ЯДРО МАНДАЛЫ:
{core_philosophy}

