async def handle_apply_patch(message: dict, websocket: WebSocket):
    session_id = message.get("session_id", "unknown")
    patch_data = message.get("patch")
    if not patch_data:
        await manager.send_to(websocket, {"type": "error", "text": "❌ Нет данных патча"})
