        async function sendFiles(files, caption) {
            if (!ws || ws.readyState !== WebSocket.OPEN) {
                showToast('◈ нет соединения', 'error');
                return;
            }
            if (caption.trim()) addUserMessage(caption);
            showThinking();

            // Показываем индикатор загрузки
            filePreview.classList.remove('hidden');
            fileProgressBar.style.width = '0%';
            filePercentEl.textContent = '0%';

            let completed = 0;
            for (const file of files) {
                // Обновляем имя текущего файла
                fileNameEl.textContent = `⏳ ${file.name}`;

                await new Promise((resolve) => {
                    const reader = new FileReader();
                    reader.onload = function(e) {
                        ws.send(JSON.stringify({
                            type: 'file',
                            name: file.name,
                            content: e.target.result.split(',')[1],
                            file_type: file.type || 'application/octet-stream',
                            caption: '',
                            session_id: currentChatId
                        }));
                        completed++;
                        const percent = Math.round((completed / files.length) * 100);
                        fileProgressBar.style.width = percent + '%';
                        filePercentEl.textContent = percent + '%';
                        resolve();
                    };
                    reader.readAsDataURL(file);
                });
                await new Promise(r => setTimeout(r, 100));
            }

            // Показываем "ожидаем подтверждения от сервера"
            fileNameEl.textContent = `✓ ${files.map(f => f.name).join(', ')}`;
            saveCurrentChatMessages();

            // Прячем через 4 сек (к этому времени file_processed уже придёт)
            setTimeout(() => {
                filePreview.classList.add('hidden');
                fileProgressBar.style.width = '0%';
                filePercentEl.textContent = '0%';
            }, 4000);
        }

